<script setup lang="ts">
import{ref,computed,watch,onUnmounted}from'vue';import{Search,ChevronRight,MapPin}from'lucide-vue-next';import{elections}from'../../repositories/elections';import{cities as catalog}from'../../composables/useLocations';import{normalize,number,percent}from'../../utils/format';import type{City,Office}from'../../types/election';import CityComparison from'../comparison/CityComparison.vue';const props=defineProps<{uf:string;office:Office}>();const rows=ref<City[]>([]),query=ref(''),sort=ref('name'),limit=ref(12),error=ref(false),loading=ref(false);let id=0;async function load(){const n=++id;loading.value=true;try{const data=await elections.cities(props.uf,props.office);if(n===id){rows.value=data;error.value=false}}catch{if(n===id){rows.value=catalog.value.filter(c=>c.uf===props.uf);error.value=true}}finally{if(n===id)loading.value=false}}watch(()=>[props.uf,props.office],()=>{query.value='';limit.value=12;rows.value=[];void load()},{immediate:true});watch(query,()=>limit.value=12);const timer=setInterval(load,60000);onUnmounted(()=>{id++;clearInterval(timer)});const filtered=computed(()=>rows.value.filter(c=>normalize(c.name).includes(normalize(query.value))).sort((a,b)=>sort.value==='name'?a.name.localeCompare(b.name,'pt-BR'):sort.value==='electorate'?(b.electorate??-1)-(a.electorate??-1):(b.progress??-1)-(a.progress??-1)));
</script>
<template><section id="municipios" class="panel cities-panel"><div class="panel-heading"><div><h2>Resultados por município</h2><p>Explore a votação em cada cidade</p></div><span class="small muted">{{rows.length}} municípios</span></div><div class="cities-controls"><label class="input-search"><Search :size="18"/><input v-model="query" placeholder="Buscar município" aria-label="Buscar município"></label><select v-model="sort" aria-label="Ordenar municípios"><option value="name">Nome: A–Z</option><option value="electorate">Maior eleitorado</option><option value="progress">Mais apurado</option></select></div><p v-if="error" class="inline-message">As estatísticas municipais estão indisponíveis. Você pode abrir os resultados de cada cidade.</p><div v-if="loading&&!rows.length" class="empty-state">Carregando municípios…</div><div class="cities-table"><div class="city-table-head"><span>MUNICÍPIO</span><span>ELEITORADO</span><span>APURADO</span><span></span></div><RouterLink v-for="c in filtered.slice(0,limit)" :key="c.code" :to="`/estado/${uf}/${c.slug}?cargo=${office}`" class="city-table-row"><span><MapPin :size="15"/>{{c.name}}<small v-if="c.capital" class="capital-tag">Capital</small></span><span>{{number(c.electorate)}}</span><strong>{{percent(c.progress)}}</strong><ChevronRight :size="16"/></RouterLink></div><div v-if="!filtered.length&&!loading" class="empty-state">Nenhum município encontrado.</div><button v-if="filtered.length>limit" class="all-candidates" @click="limit+=24">Mostrar mais municípios ({{filtered.length-limit}})</button></section><CityComparison :key="uf" :uf="uf" :cities="rows" :office="office"/></template>
